import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Context Engineering & Agentic Engineering","description":"","frontmatter":{},"headers":[],"relativePath":"tech/prompt/context-agent-engineering.md","filePath":"tech/prompt/context-agent-engineering.md","lastUpdated":1787040327000}'),r={name:"tech/prompt/context-agent-engineering.md"};function o(l,e,g,s,h,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="context-engineering-agentic-engineering" tabindex="-1">Context Engineering &amp; Agentic Engineering <a class="header-anchor" href="#context-engineering-agentic-engineering" aria-label="Permalink to &quot;Context Engineering &amp; Agentic Engineering&quot;">​</a></h1><blockquote><p>本文档整理自 Inbox 学习任务，来源包括 Anthropic 官方工程指南、Simon Willison 的 Agentic Engineering Patterns 等。</p></blockquote><h2 id="_1-context-engineering-导论" tabindex="-1">1. Context Engineering 导论 <a class="header-anchor" href="#_1-context-engineering-导论" aria-label="Permalink to &quot;1. Context Engineering 导论&quot;">​</a></h2><h3 id="_1-1-什么是-context-engineering" tabindex="-1">1.1 什么是 Context Engineering <a class="header-anchor" href="#_1-1-什么是-context-engineering" aria-label="Permalink to &quot;1.1 什么是 Context Engineering&quot;">​</a></h3><p>Context Engineering 是 Prompt Engineering 的自然进化。核心区别：</p><table tabindex="0"><thead><tr><th></th><th>Prompt Engineering</th><th>Context Engineering</th></tr></thead><tbody><tr><td><strong>焦点</strong></td><td>写什么 prompt</td><td>管理整个 context window 的 tokens</td></tr><tr><td><strong>范围</strong></td><td>一次性指令</td><td>跨多轮推理的上下文迭代管理</td></tr><tr><td><strong>时机</strong></td><td>写好 prompt 就固定</td><td>每次推理时动态决策</td></tr></tbody></table><p><strong>核心公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Context = System Instructions + Tools + MCP + External Data + Message History + ...</span></span></code></pre></div><p>Context Engineering 的本质：<strong>从不断演化的信息宇宙中，精选最有可能引导 LLM 达成目标的 token 集合</strong>。</p><h3 id="_1-2-为什么-attention-是有限资源" tabindex="-1">1.2 为什么 Attention 是有限资源 <a class="header-anchor" href="#_1-2-为什么-attention-是有限资源" aria-label="Permalink to &quot;1.2 为什么 Attention 是有限资源&quot;">​</a></h3><p>LLM 基于 Transformer 架构，每个 token 可以 attend 到上下文中的所有其他 token，形成 n² 配对关系。上下文越长，模型准确 recall 信息的能力越弱（Context Rot）。</p><p><strong>关键原则</strong>：上下文必须被视为有限资源，具有边际效益递减。LLM 和人类一样，有&quot;注意力预算&quot;。</p><p>缓解措施：</p><ul><li><strong>Position Encoding Interpolation</strong>：让模型适应更长序列</li><li><strong>Context Compression</strong>：摘要、提取、重写</li><li><strong>Semantic Chunking</strong>：智能分块，避免语义失真</li></ul><h3 id="_1-3-context-engineering-的四大支柱" tabindex="-1">1.3 Context Engineering 的四大支柱 <a class="header-anchor" href="#_1-3-context-engineering-的四大支柱" aria-label="Permalink to &quot;1.3 Context Engineering 的四大支柱&quot;">​</a></h3><ol><li><strong>检索（Retrieval）</strong>：精确检索最相关的上下文</li><li><strong>增强（Augmentation）</strong>：RAG、MCP 工具</li><li><strong>压缩（Compression）</strong>：Context 压缩技术</li><li><strong>缓存（Caching）</strong>：减少重复计算</li></ol><hr><h2 id="_2-构建有效的-agents" tabindex="-1">2. 构建有效的 Agents <a class="header-anchor" href="#_2-构建有效的-agents" aria-label="Permalink to &quot;2. 构建有效的 Agents&quot;">​</a></h2><blockquote><p>来源：<a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Anthropic - Building Effective Agents</a></p></blockquote><h3 id="_2-1-agent-的定义" tabindex="-1">2.1 Agent 的定义 <a class="header-anchor" href="#_2-1-agent-的定义" aria-label="Permalink to &quot;2.1 Agent 的定义&quot;">​</a></h3><p><strong>Workflows</strong>：通过预定义代码路径编排 LLM 和工具 <strong>Agents</strong>：LLM 动态指导自己的流程和工具使用，保持对任务完成方式的控制</p><h3 id="_2-2-何时-不-使用-agents" tabindex="-1">2.2 何时（不）使用 Agents <a class="header-anchor" href="#_2-2-何时-不-使用-agents" aria-label="Permalink to &quot;2.2 何时（不）使用 Agents&quot;">​</a></h3><p><strong>推荐做法</strong>：先用最简单的方案，只有在复杂度必须增加时才增加。</p><ul><li>优化单次 LLM 调用 + retrieval + in-context examples 通常足够</li><li>Agents 往往以延迟和成本换取更好的任务性能</li></ul><p><strong>选择 Workflow 还是 Agent</strong>：</p><ul><li>任务定义清晰、需要可预测性 → Workflow</li><li>需要灵活性和模型驱动决策 → Agent</li></ul><h3 id="_2-3-框架选择" tabindex="-1">2.3 框架选择 <a class="header-anchor" href="#_2-3-框架选择" aria-label="Permalink to &quot;2.3 框架选择&quot;">​</a></h3><p>主流框架：Claude Agent SDK、Strands Agents SDK (AWS)、Rivet (GUI)、Vellum (GUI)</p><p><strong>建议</strong>：先用 LLM API 直接实现，很多模式几行代码就能实现。如果用框架，确保理解底层代码。</p><h3 id="_2-4-agentic-系统模式" tabindex="-1">2.4 Agentic 系统模式 <a class="header-anchor" href="#_2-4-agentic-系统模式" aria-label="Permalink to &quot;2.4 Agentic 系统模式&quot;">​</a></h3><h4 id="building-block-augmented-llm" tabindex="-1">Building Block: Augmented LLM <a class="header-anchor" href="#building-block-augmented-llm" aria-label="Permalink to &quot;Building Block: Augmented LLM&quot;">​</a></h4><p>LLM 增强版 = LLM + Retrieval + Tools + Memory</p><p>推荐聚焦两个关键实现维度：</p><ol><li>针对特定用例定制化</li><li>提供易于使用的文档化接口</li></ol><p><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">MCP (Model Context Protocol)</a> 是标准化工具集成的方案。</p><h4 id="pattern-1-prompt-chaining" tabindex="-1">Pattern 1: Prompt Chaining <a class="header-anchor" href="#pattern-1-prompt-chaining" aria-label="Permalink to &quot;Pattern 1: Prompt Chaining&quot;">​</a></h4><p>将任务分解为序列步骤，每个 LLM 调用处理前一个的输出。</p><p><strong>适用场景</strong>：任务可清晰分解为固定子任务，目标是牺牲延迟换取更高准确率。</p><h4 id="pattern-2-routing" tabindex="-1">Pattern 2: Routing <a class="header-anchor" href="#pattern-2-routing" aria-label="Permalink to &quot;Pattern 2: Routing&quot;">​</a></h4><p>分类输入并引导到专用后续任务。</p><p><strong>适用场景</strong>：复杂任务有明确分类，不同类别需不同处理流程/提示/工具。</p><h4 id="pattern-3-parallelization" tabindex="-1">Pattern 3: Parallelization <a class="header-anchor" href="#pattern-3-parallelization" aria-label="Permalink to &quot;Pattern 3: Parallelization&quot;">​</a></h4><p>两种变体：</p><ul><li><strong>Sectioning</strong>：拆分为独立子任务并行运行</li><li><strong>Voting</strong>：同一任务运行多次获得多样化输出</li></ul><p><strong>适用场景</strong>：子任务可并行加速，或需要多视角/多次尝试以获得更高置信度结果。</p><h4 id="pattern-4-orchestrator-workers" tabindex="-1">Pattern 4: Orchestrator-Workers <a class="header-anchor" href="#pattern-4-orchestrator-workers" aria-label="Permalink to &quot;Pattern 4: Orchestrator-Workers&quot;">​</a></h4><p>动态分配任务给不同 worker 的编排器。</p><h4 id="pattern-5-evaluator-optimizer" tabindex="-1">Pattern 5: Evaluator-Optimizer <a class="header-anchor" href="#pattern-5-evaluator-optimizer" aria-label="Permalink to &quot;Pattern 5: Evaluator-Optimizer&quot;">​</a></h4><p>迭代优化：Evaluator 判断输出质量，Optimizer 根据反馈改进。</p><h3 id="_2-5-安全考虑" tabindex="-1">2.5 安全考虑 <a class="header-anchor" href="#_2-5-安全考虑" aria-label="Permalink to &quot;2.5 安全考虑&quot;">​</a></h3><p>Agents 可能执行超出预期的操作：</p><ul><li>最小权限原则</li><li>工具权限分层</li><li>关键操作人工确认</li><li>操作日志审计</li></ul><hr><h2 id="_3-agentic-engineering-simon-willison" tabindex="-1">3. Agentic Engineering（Simon Willison） <a class="header-anchor" href="#_3-agentic-engineering-simon-willison" aria-label="Permalink to &quot;3. Agentic Engineering（Simon Willison）&quot;">​</a></h2><blockquote><p>来源：<a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Simon Willison - Agentic Engineering Patterns</a></p></blockquote><h3 id="_3-1-定义" tabindex="-1">3.1 定义 <a class="header-anchor" href="#_3-1-定义" aria-label="Permalink to &quot;3.1 定义&quot;">​</a></h3><p><strong>Agentic Engineering</strong>：使用编码代理（coding agents）辅助软件开发。</p><p><strong>Coding Agent</strong> = 能写又能执行代码的代理。代表：Claude Code、OpenAI Codex、Gemini CLI。</p><p><strong>Agent 核心定义</strong>：Agents run tools in a loop to achieve a goal。</p><h3 id="_3-2-agentic-engineering-的核心要素" tabindex="-1">3.2 Agentic Engineering 的核心要素 <a class="header-anchor" href="#_3-2-agentic-engineering-的核心要素" aria-label="Permalink to &quot;3.2 Agentic Engineering 的核心要素&quot;">​</a></h3><p>LLM 不会从过去的错误中学习，但 coding agents 可以——前提是我们有意识地更新指令和工具 harness。</p><ol><li><strong>提供工具</strong>：给 coding agent 解决问题的工具</li><li><strong>详细说明</strong>：以正确的细节级别指定问题</li><li><strong>验证迭代</strong>：验证结果并迭代直到确信解决了问题</li></ol><h3 id="_3-3-agentic-engineering-vs-vibe-coding" tabindex="-1">3.3 Agentic Engineering vs Vibe Coding <a class="header-anchor" href="#_3-3-agentic-engineering-vs-vibe-coding" aria-label="Permalink to &quot;3.3 Agentic Engineering vs Vibe Coding&quot;">​</a></h3><p><strong>Vibe Coding</strong>（由 Andrej Karpathy 提出）：&quot;让 LLM 写代码，同时你忘记代码的存在&quot;。</p><p>关键区别：</p><ul><li>Vibe coding = 未审查的原型质量代码</li><li>Agentic engineering = 精心设计的、可验证的工程实践</li></ul><hr><h2 id="_4-prompt-engineering-最佳实践" tabindex="-1">4. Prompt Engineering 最佳实践 <a class="header-anchor" href="#_4-prompt-engineering-最佳实践" aria-label="Permalink to &quot;4. Prompt Engineering 最佳实践&quot;">​</a></h2><blockquote><p>来源：<a href="https://claude.com/blog/best-practices-for-prompt-engineering" target="_blank" rel="noreferrer">Claude - Best Practices for Prompt Engineering</a></p></blockquote><h3 id="_4-1-核心技巧" tabindex="-1">4.1 核心技巧 <a class="header-anchor" href="#_4-1-核心技巧" aria-label="Permalink to &quot;4.1 核心技巧&quot;">​</a></h3><h4 id="明确且清晰-be-explicit-and-clear" tabindex="-1">明确且清晰（Be Explicit and Clear） <a class="header-anchor" href="#明确且清晰-be-explicit-and-clear" aria-label="Permalink to &quot;明确且清晰（Be Explicit and Clear）&quot;">​</a></h4><p>现代 AI 模型对清晰明确的指令响应极好。用简单语言直接说明你想要什么。</p><p><strong>原则</strong>：告诉模型确切想看到什么。如果要全面输出，直接要求。</p><h4 id="提供上下文和动机-provide-context-and-motivation" tabindex="-1">提供上下文和动机（Provide Context and Motivation） <a class="header-anchor" href="#提供上下文和动机-provide-context-and-motivation" aria-label="Permalink to &quot;提供上下文和动机（Provide Context and Motivation）&quot;">​</a></h4><p>解释为什么某事重要，帮助模型更好理解目标，从而提供更有针对性的响应。</p><p><strong>何时提供上下文</strong>：</p><ul><li>解释输出的目的或受众</li><li>澄清约束存在的原因</li><li>描述输出如何使用</li><li>表明要解决什么问题</li></ul><h4 id="具体化-be-specific" tabindex="-1">具体化（Be Specific） <a class="header-anchor" href="#具体化-be-specific" aria-label="Permalink to &quot;具体化（Be Specific）&quot;">​</a></h4><p>具体化 = 用明确指导和需求构建指令。越具体，结果越好。</p><p><strong>包含要素</strong>：</p><ul><li>明确约束（字数、格式、时间线）</li><li>相关上下文（受众是谁、目标是什么）</li><li>期望的输出结构（表格、列表、段落）</li><li>任何要求或限制</li></ul><h4 id="使用示例-use-examples" tabindex="-1">使用示例（Use Examples） <a class="header-anchor" href="#使用示例-use-examples" aria-label="Permalink to &quot;使用示例（Use Examples）&quot;">​</a></h4><p>One-shot（一个示例）或 Few-shot（几个示例），展示比描述更容易。</p><p><strong>何时用示例</strong>：</p><ul><li>期望格式更容易展示而非描述</li><li>需要特定语气或风格</li><li>任务涉及微妙模式或惯例</li></ul><h4 id="允许表达不确定性-express-uncertainty" tabindex="-1">允许表达不确定性（Express Uncertainty） <a class="header-anchor" href="#允许表达不确定性-express-uncertainty" aria-label="Permalink to &quot;允许表达不确定性（Express Uncertainty）&quot;">​</a></h4><p>显式允许 AI 表达不确定性而非猜测，减少幻觉。</p><p>示例：<code>&quot;Analyze this data and identify trends. If the data is insufficient, say so rather than speculating.&quot;</code></p><h3 id="_4-2-高级技巧" tabindex="-1">4.2 高级技巧 <a class="header-anchor" href="#_4-2-高级技巧" aria-label="Permalink to &quot;4.2 高级技巧&quot;">​</a></h3><h4 id="prefill-ai-s-response" tabindex="-1">Prefill AI&#39;s Response <a class="header-anchor" href="#prefill-ai-s-response" aria-label="Permalink to &quot;Prefill AI&#39;s Response&quot;">​</a></h4><p>预填充 AI 的响应，引导格式、语气或结构。对于强制输出 JSON 等结构化格式特别有用。</p><h4 id="xml-tagging" tabindex="-1">XML Tagging <a class="header-anchor" href="#xml-tagging" aria-label="Permalink to &quot;XML Tagging&quot;">​</a></h4><p>使用 XML 标签（如 <code>&lt;context&gt;</code>、<code>&lt;instructions&gt;</code>）组织 prompt 的不同部分，虽然模型越来越强大后重要性在降低。</p><h4 id="chain-of-thought" tabindex="-1">Chain of Thought <a class="header-anchor" href="#chain-of-thought" aria-label="Permalink to &quot;Chain of Thought&quot;">​</a></h4><p>对于复杂推理，在给出最终答案前引导模型&quot;思考&quot;。<code>Let me think through this step by step</code> 可以显著改善数学和逻辑任务。</p><h4 id="role-prompting" tabindex="-1">Role Prompting <a class="header-anchor" href="#role-prompting" aria-label="Permalink to &quot;Role Prompting&quot;">​</a></h4><p>定义角色（如&quot;你是一位资深 SRE 工程师&quot;），让模型以该角色的视角响应。</p><hr><h2 id="_5-agent-sdk-对比" tabindex="-1">5. Agent SDK 对比 <a class="header-anchor" href="#_5-agent-sdk-对比" aria-label="Permalink to &quot;5. Agent SDK 对比&quot;">​</a></h2><h3 id="_5-1-claude-agent-sdk" tabindex="-1">5.1 Claude Agent SDK <a class="header-anchor" href="#_5-1-claude-agent-sdk" aria-label="Permalink to &quot;5.1 Claude Agent SDK&quot;">​</a></h3><p><strong>核心概念</strong>：Tools、Memory、Conversation</p><p><strong>优势</strong>：</p><ul><li>与 Claude 模型深度集成</li><li>支持复杂多步骤 agent</li><li>内置 streaming 和 async 支持</li></ul><p><strong>适用场景</strong>：需要 Claude 特有能力的 agent 应用</p><p><strong>官方文档</strong>：<a href="https://claude.com/blog/building-agents-with-the-claude-agent-sdk" target="_blank" rel="noreferrer">https://claude.com/blog/building-agents-with-the-claude-agent-sdk</a></p><h3 id="_5-2-openai-agents-python-sdk" tabindex="-1">5.2 OpenAI Agents Python SDK <a class="header-anchor" href="#_5-2-openai-agents-python-sdk" aria-label="Permalink to &quot;5.2 OpenAI Agents Python SDK&quot;">​</a></h3><p><strong>核心概念</strong>：Handoffs、Guardrails、Persistence</p><p><strong>优势</strong>：</p><ul><li>多 agent 协作（Handoff 模式）</li><li>Guardrails 输入输出安全过滤</li><li>Conversation persistence 内置</li><li>需 Python 3.10+</li></ul><p><strong>适用场景</strong>：复杂多 agent 系统，需要输入安全过滤</p><p><strong>官方文档</strong>：<a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noreferrer">https://github.com/openai/openai-agents-python</a></p><h3 id="_5-3-其他框架" tabindex="-1">5.3 其他框架 <a class="header-anchor" href="#_5-3-其他框架" aria-label="Permalink to &quot;5.3 其他框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>框架</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td>LangChain</td><td>生态最全面</td><td>快速原型</td></tr><tr><td>LangGraph</td><td>图结构编排</td><td>复杂工作流</td></tr><tr><td>LlamaIndex</td><td>知识检索增强</td><td>RAG 应用</td></tr><tr><td>AutoGen</td><td>多 agent 协作</td><td>复杂多角色场景</td></tr></tbody></table><hr><h2 id="_6-agent-评估方法" tabindex="-1">6. Agent 评估方法 <a class="header-anchor" href="#_6-agent-评估方法" aria-label="Permalink to &quot;6. Agent 评估方法&quot;">​</a></h2><h3 id="_6-1-swe-bench-pro" tabindex="-1">6.1 SWE-Bench Pro <a class="header-anchor" href="#_6-1-swe-bench-pro" aria-label="Permalink to &quot;6.1 SWE-Bench Pro&quot;">​</a></h3><p><strong>来源</strong>：<a href="https://labs.scale.com/blog/agentic-rubrics" target="_blank" rel="noreferrer">Scale AI - Agentic Rubrics</a></p><p>SWE-Bench Pro 是评估 coding agent 能力的基准测试，核心评估维度：</p><ul><li><strong>准确性</strong>：agent 的解决方案是否正确</li><li><strong>效率</strong>：消耗多少 token 和时间</li><li><strong>鲁棒性</strong>：对边缘 case 的处理能力</li></ul><h3 id="_6-2-评估设计原则" tabindex="-1">6.2 评估设计原则 <a class="header-anchor" href="#_6-2-评估设计原则" aria-label="Permalink to &quot;6.2 评估设计原则&quot;">​</a></h3><ol><li><strong>定义清晰的成功标准</strong>：可量化的指标</li><li><strong>构建评估集</strong>：代表性的 test cases</li><li><strong>自动化 + 人工结合</strong>：自动跑 case，人工评估质量</li><li><strong>追踪关键指标</strong>：准确率、召回率、token 消耗、延迟</li></ol><h3 id="_6-3-常见坑" tabindex="-1">6.3 常见坑 <a class="header-anchor" href="#_6-3-常见坑" aria-label="Permalink to &quot;6.3 常见坑&quot;">​</a></h3><ul><li>评估标准与实际用户体验存在 gap</li><li>自动化评估难以覆盖所有边缘 case</li><li>游戏/前端等视觉类任务需要人工判断</li></ul><hr><h2 id="_7-相关资源" tabindex="-1">7. 相关资源 <a class="header-anchor" href="#_7-相关资源" aria-label="Permalink to &quot;7. 相关资源&quot;">​</a></h2><ul><li><a href="https://platform.claude.com/docs/en/build-with-claude/prompt-engineering/overview" target="_blank" rel="noreferrer">Claude Prompt Engineering 官方文档</a></li><li><a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Anthropic Context Engineering Guide</a></li><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Building Effective Agents</a></li><li><a href="https://simonwillison.net/guides/agentic-engineering-patterns/" target="_blank" rel="noreferrer">Simon Willison - Agentic Engineering Patterns</a></li><li><a href="https://claude.com/blog/building-agents-with-the-claude-agent-sdk" target="_blank" rel="noreferrer">Claude Agent SDK</a></li><li><a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noreferrer">OpenAI Agents Python SDK</a></li><li><a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">Model Context Protocol</a></li></ul>',126)])])}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
